package main

import "testing"

func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestMainEntryPoint(t *testing.T) {
	tests := []struct {
		name      string
		wantPanic bool
	}{
		{name: "first invocation", wantPanic: false},
		{name: "second invocation", wantPanic: false},
		{name: "invocation after add", wantPanic: false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			defer func() {
				gotPanic := recover() != nil
				if gotPanic != tt.wantPanic {
					t.Fatalf("main() panic = %v, want %v", gotPanic, tt.wantPanic)
				}
			}()
			if tt.name == "invocation after add" {
				_ = add(1, 2)
			}
			main()
		})
	}
}

